// judge-validation/conditional-building.adversarial.ts
import { JudgeHarness } from './harness'
import conditionalJudge from '../judges/systems/conditional-building.xml'

describe('Conditional Building Judge - Adversarial', () => {

  // Test: Judge MUST catch this
  it('catches permission check disguised as business logic', () => {
    const code = `
      async function getReport(userId: string) {
        const user = await db.users.get(userId)
        // Looks like business logic but IS a permission check
        if (user.department === 'finance') {
          return await generateFinanceReport()
        }
        return await generateGeneralReport()
      }
    `
    const result = JudgeHarness.evaluate(conditionalJudge, code)
    expect(result.violations).toContainEqual(
      expect.objectContaining({
        criterion: 'Separation of Concerns',
        severity: 'critical',
      })
    )
  })

  // Test: Judge must NOT false-positive on this
  it('does not flag legitimate business branching', () => {
    const code = `
      // This is real business logic, not a permission check
      function calculateShipping(weight: number, distance: number) {
        if (weight > 50) return calculateHeavyFreight(weight, distance)
        return calculateStandardShipping(weight, distance)
      }
    `
    const result = JudgeHarness.evaluate(conditionalJudge, code)
    expect(result.violations.filter(v => v.criterion === 'Separation of Concerns')).toHaveLength(0)
  })

  // Test: Sophisticated evasion attempt
  it('catches spread-out permission checks across helpers', () => {
    const code = `
      // Evasion: permission check split across "utility" functions
      const isPrivileged = (user) => user.role === 'admin'
      const canAccess = (user, resource) => isPrivileged(user) || resource.ownerId === user.id

      async function updateResource(userId, resourceId, data) {
        const user = await getUser(userId)
        const resource = await getResource(resourceId)
        if (!canAccess(user, resource)) throw new Error('nope')
        // Still inline permission logic, just extracted to helpers
        return await db.update(resourceId, data)
      }
    `
    const result = JudgeHarness.evaluate(conditionalJudge, code)
    // Should still flag: permission check is in business logic, not a guard
    expect(result.grades['Separation of Concerns']).toBeOneOf(['D', 'C'])
  })
})

