step_definition_standards.code:
// steps/user-profile.steps.ts
// AUTO-GENERATED FROM: features/user-profile.feature
// STATUS: AWAITING HUMAN REVIEW
// IMPORTANT: Review each step for correctness before approving

import { Given, When, Then } from '@cucumber/cucumber'
import { expect, Page } from '@playwright/test'

// Background steps
Given('I am logged in as a standard user', async function () {
  await this.page.goto('/login')
  await this.page.fill('[data-testid="email"]', this.testUser.email)
  await this.page.fill('[data-testid="password"]', this.testUser.password)
  await this.page.click('[data-testid="login-btn"]')
  await this.page.waitForURL('/dashboard')
})

Given('I am on the profile page', async function () {
  await this.page.goto('/profile')
  await this.page.waitForSelector('[data-testid="profile-name"]')
})

// Action steps
When('I click the edit button', async function () {
  await this.page.click('[data-testid="edit-profile-btn"]')
  await this.page.waitForSelector('[data-testid="profile-name-input"]')
})

When('I change my name to {string}', async function (name: string) {
  await this.page.fill('[data-testid="profile-name-input"]', name)
})

When('I clear the name field', async function () {
  await this.page.fill('[data-testid="profile-name-input"]', '')
})

When('I click save', async function () {
  await this.page.click('[data-testid="save-profile-btn"]')
})

When('I enter {string} in the name field', async function (input: string) {
  await this.page.fill('[data-testid="profile-name-input"]', input)
})

// Assertion steps
Then('I should see my current name', async function () {
  const name = await this.page.textContent('[data-testid="profile-name"]')
  expect(name).toBeTruthy()
})

Then('I should see a success confirmation', async function () {
  await this.page.waitForSelector('[data-testid="toast-success"]')
})

Then('I should see a validation error on the name field', async function () {
  await this.page.waitForSelector('[data-testid="name-field-error"]')
})

Then('the form should not submit', async function () {
  // Verify we're still in edit mode
  await expect(this.page.locator('[data-testid="profile-name-input"]')).toBeVisible()
})

Then('my name should display as {string}', async function (expected: string) {
  await this.page.waitForSelector('[data-testid="profile-name"]')
  const name = await this.page.textContent('[data-testid="profile-name"]')
  expect(name).toBe(expected)
})

