// VIOLATION: This test was AI-generated and confirms the implementation
// rather than challenging it. It mocks everything, tests nothing real.
describe('UserService', () => {
  it('should update user', async () => {
    const mockDb = { update: vi.fn().mockResolvedValue({ id: '1', name: 'Test' }) }
    const service = new UserService(mockDb)
    const result = await service.updateUser('1', { name: 'Test' })
    expect(mockDb.update).toHaveBeenCalledWith('1', { name: 'Test' })
    expect(result).toEqual({ id: '1', name: 'Test' })
    // This tests that the mock returns what we told it to return.
    // It tests NOTHING about actual behavior.
  })

  // VIOLATION: No error cases
  // VIOLATION: No edge cases
  // VIOLATION: No concurrency cases
  // VIOLATION: Description says "should update user" - implementation language, not behavior
})

describe('User Profile Update', () => {
  // Behavior language, not implementation language
  it('persists name change and reflects in subsequent reads', async () => {
    const service = createTestService()  // Real service, test DB
    await service.updateUser('1', { name: 'New Name' })
    const user = await service.getUser('1')
    expect(user.name).toBe('New Name')
  })

  it('rejects empty name with validation error', async () => {
    const service = createTestService()
    await expect(
      service.updateUser('1', { name: '' })
    ).rejects.toThrow(ValidationError)
  })

  it('handles concurrent updates without data loss', async () => {
    const service = createTestService()
    // Simulate concurrent edits
    await Promise.all([
      service.updateUser('1', { name: 'Alice' }),
      service.updateUser('1', { email: 'bob@test.com' }),
    ])
    const user = await service.getUser('1')
    // Both changes should be reflected (not one overwriting the other)
    expect(user.name).toBe('Alice')
    expect(user.email).toBe('bob@test.com')
  })

  it('rejects update when auth token expired mid-request', async () => {
    const service = createTestService({ tokenExpiresIn: 0 })
    await expect(
      service.updateUser('1', { name: 'Test' })
    ).rejects.toThrow(AuthError)
  })

  it('truncates or rejects name exceeding 500 characters', async () => {
    const service = createTestService()
    const longName = 'A'.repeat(501)
    await expect(
      service.updateUser('1', { name: longName })
    ).rejects.toThrow(ValidationError)
  })
})

// VIOLATION: This is E2E masquerading as UAT
// No human checkpoint. No pause. No checklist.
test('UAT: user can update profile', async ({ page }) => {
  await page.goto('/profile')
  await page.click('[data-testid="edit-btn"]')
  await page.fill('[data-testid="name"]', 'New Name')
  await page.click('[data-testid="save-btn"]')
  // VIOLATION: Machine assertion pretending to be UAT
  await expect(page.locator('[data-testid="name"]')).toHaveText('New Name')
  // Human never saw this. Human never verified the visual state.
  // This is not UAT. This is E2E with a misleading name.
})
